function heading(string $eyebrow, string $title, string $subtitle, bool $button = false): void { ?><div class="page-heading"><div><p class="eyebrow"><?=e($eyebrow)?></p><h1><?=e($title)?></h1><p><?=e($subtitle)?></p></div><?php if ($button): ?><a class="button" href="/form-daftar.php"><?=icon('plus')?> Tambah siswa</a><?php endif ?></div><?php }
function student_table(array $rows, bool $compact = false, int $offset = 0): void { ?><div class="table-wrap"><table><caption class="sr-only">Daftar calon siswa pada ruang demo Anda</caption><thead><tr><th scope="col">NO.</th><th scope="col">NAMA SISWA</th><th scope="col">SEKOLAH ASAL</th><th scope="col">PAS FOTO</th><?php if (!$compact): ?><th scope="col">AGAMA</th><?php endif ?><th scope="col" class="right">AKSI</th></tr></thead><tbody><?php foreach ($rows as $i => $row): ?><tr><td class="row-number"><?=str_pad((string)($offset+$i+1),2,'0',STR_PAD_LEFT)?></td><td><a class="student-name" href="/detail.php?id=<?=$row['id']?>"><?=photo_tag($row, 'avatar table-photo')?><span><strong><?=e($row['nama'])?></strong><small>PPDB-<?=str_pad((string)$row['id'],4,'0',STR_PAD_LEFT)?></small></span></a></td><td><?=e($row['sekolah_asal'])?></td><td><span class="photo-status <?=$row['foto_mime'] ? 'complete' : 'pending'?>"><?=$row['foto_mime'] ? 'Lengkap' : 'Perlu foto'?></span></td><?php if (!$compact): ?><td><?=e($row['agama'])?></td><?php endif ?><td><div class="row-actions"><a href="/detail.php?id=<?=$row['id']?>" aria-label="Lihat <?=e($row['nama'])?>" title="Lihat detail"><?=icon('eye')?></a><a href="/form-edit.php?id=<?=$row['id']?>" aria-label="Edit <?=e($row['nama'])?>" title="Edit siswa"><?=icon('edit')?></a><a class="danger-text" href="/hapus.php?id=<?=$row['id']?>" aria-label="Hapus <?=e($row['nama'])?>" title="Hapus siswa"><?=icon('trash')?></a></div></td></tr><?php endforeach ?></tbody></table></div><?php }
